<section class="page-heading"><div><p class="eyebrow">VOTRE COLLECTION PERSONNELLE</p><h1>Ma garde-robe</h1><p class="subheading">Toutes vos pieces, soigneusement organisees.</p></div><a class="button primary" href="<?= e(url('clothes-create')) ?>">+ Ajouter une piece</a></section>
<form class="filter-bar wardrobe-filters" method="get"><input type="hidden" name="page" value="clothes"><label class="search-field"><span>&#8981;</span><input name="q" placeholder="Nom, couleur ou marque" value="<?= e($query) ?>"></label><select name="label" aria-label="Libelle"><option value="">Tous les libelles</option><?php foreach($labels as $label): ?><option value="<?= e($label['id']) ?>" <?= (string)$selectedLabel===(string)$label['id']?'selected':'' ?>><?= e($label['name']) ?></option><?php endforeach; ?></select><select name="category" aria-label="Categorie"><option value="">Toutes les categories</option><?php foreach($categories as $cat): ?><option value="<?= e($cat['id']) ?>" <?= (int)$filterValues['category']===(int)$cat['id']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach; ?></select><select name="status" aria-label="Etat"><option value="">Tous les etats</option><?php foreach(['available'=>'Disponible','laundry'=>'Au lavage','repair'=>'A reparer','unavailable'=>'Indisponible','archived'=>'Archive'] as $key=>$text): ?><option value="<?= e($key) ?>" <?= $selectedStatus===$key?'selected':'' ?>><?= e($text) ?></option><?php endforeach; ?></select><input name="color" placeholder="Couleur" value="<?= e($filterValues['color']) ?>"><input name="brand" placeholder="Marque" value="<?= e($filterValues['brand']) ?>"><input name="size" placeholder="Taille" value="<?= e($filterValues['size']) ?>"><input name="season" placeholder="Saison" value="<?= e($filterValues['season']) ?>"><input name="style" placeholder="Style" value="<?= e($filterValues['style']) ?>"><input type="number" name="min_price" min="0" step="0.01" placeholder="Prix min" value="<?= e($filterValues['min_price']) ?>"><input type="number" name="max_price" min="0" step="0.01" placeholder="Prix max" value="<?= e($filterValues['max_price']) ?>"><input name="price_currency" maxlength="3" placeholder="Devise prix" value="<?= e($filterValues['price_currency']) ?>"><select name="sort" aria-label="Tri"><option value="newest" <?= $sort==='newest'?'selected':'' ?>>Plus recentes</option><option value="oldest" <?= $sort==='oldest'?'selected':'' ?>>Plus anciennes</option><option value="name" <?= $sort==='name'?'selected':'' ?>>Nom</option><option value="brand" <?= $sort==='brand'?'selected':'' ?>>Marque</option></select><select name="view" aria-label="Affichage"><option value="grid" <?= $viewMode==='grid'?'selected':'' ?>>Grille</option><option value="list" <?= $viewMode==='list'?'selected':'' ?>>Liste</option></select><button class="button secondary" type="submit">Filtrer</button></form>
<?php if(!$clothes): ?><div class="empty-state"><h3><?= $query||$selectedLabel||$selectedStatus?'Aucune piece ne correspond':'Votre collection est encore vide' ?></h3><p>Modifiez les filtres ou ajoutez vos premieres pieces.</p><a class="button primary" href="<?= e(url('clothes-create')) ?>">Ajouter une piece &rarr;</a></div><?php else: ?><p class="result-count"><?= e($totalItems) ?> piece<?= $totalItems>1?'s':'' ?></p><div class="clothes-grid <?= $viewMode==='list'?'list-view':'' ?>"><?php foreach($clothes as $item): ?><a class="clothing-card" href="<?= e(url('clothes-show',['id'=>$item['id']])) ?>"><div class="clothing-photo"><?php if($item['image_path']): ?><img loading="lazy" src="<?= e(APP_BASE_URL.'/'.$item['image_path']) ?>" alt="<?= e($item['name']) ?>"><?php else: ?><span>GRINGO</span><?php endif; ?><span class="status-pill"><?= e(['available'=>'Disponible','laundry'=>'Au lavage','repair'=>'A reparer','unavailable'=>'Indisponible','archived'=>'Archive'][$item['status']]??$item['status']) ?></span></div><div class="clothing-meta"><span><?= e($item['label_name']) ?></span><h3><?= e($item['name']) ?></h3><span class="rating-display" aria-label="Note : <?= e($item['rating']??0) ?> sur 5"><?php for($star=1;$star<=5;$star++): ?><span class="<?= $star<=(int)($item['rating']??0)?'is-filled':'' ?>">★</span><?php endfor; ?></span><p><?= e(implode(' · ',array_filter([$item['brand'],$item['color'],$item['size']]))) ?></p></div></a><?php endforeach; ?></div><?php if($totalPages>1): ?><nav class="pagination" aria-label="Pagination"><?php if($currentPage>1): ?><a class="button secondary" href="<?= e(url('clothes',array_merge(['p'=>$currentPage-1],$filterValues,['q'=>$query,'label'=>$selectedLabel,'status'=>$selectedStatus,'sort'=>$sort,'view'=>$viewMode]))) ?>">&larr; Precedent</a><?php endif; ?><span>Page <?= e($currentPage) ?> sur <?= e($totalPages) ?></span><?php if($currentPage<$totalPages): ?><a class="button secondary" href="<?= e(url('clothes',array_merge(['p'=>$currentPage+1],$filterValues,['q'=>$query,'label'=>$selectedLabel,'status'=>$selectedStatus,'sort'=>$sort,'view'=>$viewMode]))) ?>">Suivant &rarr;</a><?php endif; ?></nav><?php endif; ?><?php endif; ?>